}

export interface WorkUnit {
  id: string;
  title: string;
  role?: AgentRole;
  prompt: string;
  dependsOn: string[];
  requires: WorkRequirements;
  /** False for advisory work: reported, run when possible, never awaited for completion. */
  required?: boolean;
  /** X-Task-Class routing hint for this unit (used when the resource has none of its own). */
  taskClass?: string;
  status: WorkUnitStatus;
  /** Resource the unit last ran on (its conversation continues from there). */
  assignment?: { resourceId: string; model: string; since: string };
  /** Operator-authorized assignment that replaces requirement matching for this unit. */
  override?: { resourceId: string; overriding: string[]; decisionId: string };
  /** Durable task state holding the unit's conversation, for resumption without live model context. */
  agentTaskId?: string;
  parked?: { since: string; reason: string; resourceIds: string[]; wakeAt?: string };
  blocked?: { since: string; reason: string; decision: EscalationDecision };
  /** A decision applied since the unit last ran, told to the unit when it resumes. */
  pendingDecision?: { label: string; note?: string; restart?: boolean };
  decisions?: AppliedDecision[];
  dropped?: boolean;
  result?: {
    summary: string;
    completedAt: string;
    resourceId: string;
    outcome: string;
    overriding?: string[];
    /** The verifier run behind the outcome, kept so dependent review units see it where nothing was integrated. */
    verification?: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false };
  };
  /**
   * The verifier run behind the unit's latest failure, present only while that failure is its last outcome: a
   * dependent failure_debugger of an isolated operation is given it as evidence while the unit waits on the operator.
   */
  failedRun?: { at: string; reason: string; summary: string; verification: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false } };
  reroutes: Array<{ at: string; from: string; to: string; reason: string }>;
  runs: number;
  /** `runs` when the operator last authorized more attempts (the run budget counts from here). */
  runsBase?: number;
  /** Executions started whose inference outcome was never received (process ended mid-run). */
  unknownResumes: number;
  modelsUsed: string[];
  /**
   * Operator cap on this unit's prompt context, in tokens. The resource's advertised capacity still applies; a unit
   * whose start prompt cannot fit this budget is blocked before any inference.
   */
  contextBudget?: number;
  /** Operator-declared paths a reviewed change may touch; a reviewer's evidence package carries it, and a diff outside it is rejected. */
  authorizedScope?: string[];
  /** Named inputs the unit's role contract requires (specialists); enforced before the unit starts. */
  inputs?: Record<string, string>;
  /** Hash of the effective inputs last submitted in this unit's conversation; a resume repeats them only on change. */
  renderedInputsHash?: string;
  /** Results the executor refused (for example a specialist output that failed its contract), most recent last. */
  rejectedOutputs?: StoredRejectedOutput[];
  /** What the unit's start prompt was estimated to need, and the budget it was checked against. */
  context?: {
    estimatedPromptTokens: number;
    budgetTokens: number;
    contextLimit: number;
    at: string;
    /** Which bound decided the check. Absent on records written before v1.1. */
  files: string[];
  outcome: string;
  summary: string;
  verification: "PASSED" | "PASSED_POSTHOC" | "PASSED_UNBOUND" | "PASSED_POSTHOC_UNBOUND" | "NOT_RUN" | "ALREADY_INTEGRATED" | "ALREADY_MERGED" | "NO_CHANGES";
  /** Content-addressed view of the merged unit's tree; absent when the worktree was already gone. */
  candidate?: { digest: string; scope: "tree" | "commit" };
  /** The unit's executed verifier, copied verbatim from its result; absent when the unit produced none. */
  tests?: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false };
  /** 1-based merge order within the operation, assigned by the runner. */
  sequence?: number;
}

