  private classifySpecialist(unit: WorkUnit, role: SpecialistRole, raw: string, outcome: string): UnitRunResult {
    const reject = (why: string): UnitRunResult => {
      const reason = `specialist result rejected: ${why}`.slice(0, 300);
      return {
