    const evidence = result.evidence.slice(0, 40).map((item) => `- ${JSON.stringify(item.path)}${item.lineRange ? ` lines ${item.lineRange[0]}-${item.lineRange[1]}` : ""}: ${JSON.stringify(item.note)}`);
